def solution(input_str):
    """
    Solves the caterpillar problem by computing minimum merges needed.
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "0\n"

    n, m = map(int, lines[0].split())

    if n == 0:
        return "0\n"
    if m == 0:
        return f"{n - 1}\n"

    # Build adjacency info and detect cycles using Union-Find
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def unite(x, y):
        px, py = find(x), find(y)
        if px == py:
            return True
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return False

    edges_count = 0
    cycle_count = 0
    for line in lines[1:min(m + 1, len(lines))]:
        if not line.strip():
            continue
        parts = line.strip().split()
        if len(parts) >= 2:
            a, b = int(parts[0]), int(parts[1])
            if unite(a, b):
                cycle_count += 1
            edges_count += 1

    # Formula: k = max(0, n - m - 1 + cycles_adjustment)
    base_ops = n - m - 1

    # Adjust based on structure
    if cycle_count > 0:
        # Each independent cycle needs at least 1 extra merge
        base_ops += cycle_count
    elif base_ops < 0:
        # Graph has more edges than a tree needs with current vertex count
        # Means we have cycles that need breaking
        base_ops = max(base_ops, 0)

    # Account for disconnected graph needing connections
    # Count components
    active_components = 0
    for i in range(1, n + 1):
        if parent[i] == i:
            active_components += 1

    # If multiple components exist, more merges needed
    if active_components > 1:
        base_ops = max(base_ops, active_components - 1)

    return f"{max(0, base_ops)}\n"

