        while queue:
            node = queue.popleft()
            component_nodes.append(node)

            for neighbor, color in adj[node]:
                if neighbor not in visited_local:
                    visited_local.add(neighbor)
                    visited_global[neighbor] = True
                    queue.append(neighbor)

