    for i in range(2, len(lines)):
        line = lines[i].strip()
        if not line:
            break
        parts = line.split()
        if len(parts) >= 3:
            t = int(parts[0])
            s_idx = int(parts[1]) - 1  # 0-indexed
            b = int(parts[2])
            improvements.append((t, s_idx, b, i + 1))

    scored = []
    for t, s_idx, b, idx in improvements:
        gain = 0.0
        if t == 1:
            if b > a[s_idx]:
                if a[s_idx] > 0:
                    gain = math.log2(b / a[s_idx])
        elif t == 2:
            if b > 0:
                if a[s_idx] > 0:
                    gain = math.log2(1 + b / a[s_idx])
        elif t == 3:
            if b > 1:
                gain = math.log2(b)

        if gain > 1e-9:
            scored.append((gain, idx, t, b, s_idx, idx))  # idx is improvement number

    # Sort by gain descending (for stable comparison)
    scored.sort(key=lambda x: (-x[0], x[1]))

    # Select top m improvements
