    topo_order = []

    while queue:
        curr = queue.pop(0)
        topo_order.append(curr)
        for neighbor in adj[curr]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) != num_chains:
        return '0\n'

    # Build final permutation
    result = []
    for chain_idx in topo_order:
        result.extend(chains[chain_idx])

    # Validate
    result_set = set(result)
    if len(result) != n or len(result_set) != n:
        return '0\n'

    # Check prerequisites
    for node_idx in range(n):
        node = node_idx + 1
        prereq = p[node_idx]
        if prereq != 0:
            pos_node = result.index(node)
            pos_prereq = result.index(prereq)
            if pos_node <= pos_prereq:
                return '0\n'

    # Check special pairs
    for x, y in special_pairs:
        pos_x = result.index(x)
        pos_y = result.index(y)
        if pos_y != pos_x + 1:
            return '0\n'

    return ' '.join(map(str, result)) + '\n'

