def rev(x):
    """Reverse the digits of a number."""
    return int(str(x)[::-1])

def count_lucky_tickets(x, y, memo):
    """Count lucky tickets (a, b) where a*b = rev(a)*rev(b) for 1 <= a <= x, 1 <= b <= y."""
    if (x, y) in memo:
        return memo[(x, y)]

    count = 0
    for a in range(1, x + 1):
        ra = rev(a)
        for b in range(1, y + 1):
            if a * b == ra * rev(b):
                count += 1
    memo[(x, y)] = count
    return count

