        return '-1\n'

    # Check if multisets match
    if sorted(initial) != sorted(target):
        return '-1\n'

    start_tuple = tuple(sorted(initial))
    if start_tuple == tuple(sorted(target)):
        return '0\n'

    end_tuple = tuple(sorted(target))

    # BFS
    q = deque([(start_tuple, [])])
    visited = {start_tuple}

    while q:
        state, ops = q.popleft()

        # Limit operations
        if len(ops) >= 1000:
            continue

        # Count occurrences of each position
        counts = {}
        for x in state:
            counts[x] = counts.get(x, 0) + 1

        # Get unique positions sorted
        unique_positions = sorted(counts.keys())
        n_unique = len(unique_positions)

        # Try all pairs
