                new_counts[src] -= 1
                if new_counts[src] == 0:
                    del new_counts[src]

                new_counts[dest] = new_counts.get(dest, 0) + 1

                # Rebuild state from counts
                new_state = []
                for pos in new_counts:
                    for _ in range(new_counts[pos]):
