    edges = []
    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        edges.append((w, u - 1, v - 1))

    # If we have enough edges to potentially bypass constraints (m > n-1),
    # or pre-assigned edges contain cycles, we can achieve weight 0 in many cases.
    # If exactly n-1 edges form a valid spanning tree, answer is their weight sum.

    parent = list(range(n))
    rank = [0] * n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    # Run Kruskal's on pre-assigned edges
    edges.sort(key=lambda x: x[0])

    mst_weight = 0
    edges_count = 0

    for w, u, v in edges:
        if union(u, v):
            mst_weight += w
            edges_count += 1
            if edges_count == n - 1:
                break

    # If we formed a complete spanning tree with pre-assigned edges
    if edges_count == n - 1:
        return str(mst_weight)

    # Otherwise, we have flexibility
    return '0'

