    # For each left half, compute the match pattern vector
    left_patterns = {}

    for left_mask in range(1 << mid):
        pattern = []
        for gstr, cnt in guesses:
            match = 0
            for j in range(mid):
                our_bit = (left_mask >> j) & 1
                guess_bit = 1 if gstr[j] == '1' else 0
                if our_bit == guess_bit:
                    match += 1
            pattern.append(match)
        key = tuple(pattern)
        left_patterns[key] = left_patterns.get(key, 0) + 1

    # For each right half, see if it can complete a valid code
    result = 0

    for right_mask in range(1 << (n - mid)):
        pattern = []
        right_total = []

        for gstr, cnt in guesses:
            match = 0
            for j in range(n - mid):
                our_bit = (right_mask >> j) & 1
                guess_bit = 1 if gstr[mid + j] == '1' else 0
                if our_bit == guess_bit:
                    match += 1
            right_total.append(match)

        # For each possible left pattern, check if we can satisfy all constraints
