            valid_prev = 0
            for i in range(j - m, j):  # planets where next could reach j
                if i >= 1:
                    valid_prev += dp[i]
            new_dp[j] = valid_prev
        dp = new_dp

    # Sum all valid sequences
    return str(sum(dp) % MOD)

