            return 0
        if r == 0 or r == n_val:
            return 1
        if r > n_val // 2:
            r = n_val - r

        result = 1
        for i in range(r):
            result = result * (n_val - i) // (i + 1)
        return result

    def estimate_max_at_k(k_val):
        """
        Estimate max(A_k) using the binomial coefficient bound:
        max(A_k) >= C(k + n - 1, n - 1)
        """
        if k_val < 0:
            return 1  # base case
        return compute_binomial_large(k_val + n - 1, n - 1)

